// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeSubjectEdition = function (meta, rows) {
  const {subject, year, grade, contest, letters, tasksFile, answersFile, language} = meta;
  const folder = 'assets/' + subject + '/' + year + '/';
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(row => {
    const {title, question, choices, figure, figures, optionFigures, steps, context, audio, numericAnswer} = row;
    const condition = figures?.length ? {items: figures} : figure;
    const options = choices.map((text, i) => {
      const image = optionFigures?.[i];
      if (!image) return {text};
      return {text: row.showOptionText ? text : '', image: image.src,
        description: row.showOptionText ? text + '. ' + image.alt : image.alt,
        ...(image.detailSrc ? {detailSrc: image.detailSrc} : {}),
        pixelWidth: image.width, pixelHeight: image.height};
    });
    return {
      title, question, choices, language, context, guided: true, hideIntroText: true,
      skill: contest, answer: row.answer ?? null,
      points: row.points ?? meta.points,
      ...(row.adaptation ? {questionNote: row.adaptation} : {}),
      ...(row.number ? {number: row.number} : {}),
      ...(Number.isInteger(numericAnswer) ? {numericAnswer} : {}),
      ...(audio ? {audio: folder + (meta.listeningFile ?? 'listening.mp3')} : {}),
      ...(condition || optionFigures ? {choiceLayout: {condition, options},
        choiceImages: options.map(option => option.image),
        ...(condition?.src ? {conditionImage: condition.src, conditionAlt: condition.alt} : {})} : {}),
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ...steps.map((explanation, index) => index === steps.length - 1
          ? ['Проверка', 'Проверка', explanation]
          : [index ? 'Шаг ' + (index + 1) : 'Первый шаг', 'Рассуждение', explanation]),
        ['Ответ', 'Ответ', ''],
      ],
    };
  });
  for (const group of meta.matchingGroups ?? []) {
    const parts = lessons.slice(group.start - 1, group.start - 1 + group.count);
    if (parts.length !== group.count || parts.some(part => !part.conditionImage ||
        JSON.stringify(part.choices) !== JSON.stringify(parts[0].choices))) throw new Error('Incomplete matching group ' + group.title);
    const steps = [
      ['Выбор', 'Условие задачи', ''],
      ...parts.map((part, index) => ['Рисунок ' + (index + 1), part.title,
        part.steps.slice(1, -1).map(step => step[2]).join(' ')]),
      ['Ответ', 'Все пары', ''],
    ];
    for (const part of parts) Object.assign(part, {matching: group, title: group.title, question: group.question, steps});
  }
  return {
    id: [year, subject, meta.session, grade, meta.editionSuffix].filter(Boolean).join('-'), year, grades,
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы') + (meta.sessionTitle ? ' · ' + meta.sessionTitle : '') + (meta.editionLabel ? ' · ' + meta.editionLabel : ''),
    ...(meta.sections ? {sections: meta.sections} : {}),
    ...(meta.titleLanguage ? {titleLanguage: meta.titleLanguage} : {}),
    subject, answerLetters: [...letters], sources: {
      contest, tasksUrl: folder + tasksFile, answersUrl: folder + answersFile,
      ...(meta.reviewedKey ? {reviewedKey: true} : {}),
    },
    lessons, scenes: lessons.map(() => () => ''),
  };
};

register(globalThis.makeSubjectEdition({"subject":"british-bulldog","year":2018,"grade":"7-8","contest":"British Bulldog","letters":"ABCD","count":60,"language":"en","points":3,"tasksFile":"7-8/variant-1/tasks.pdf","answersFile":"reviewed-7-8.pdf","listeningFile":"7-8/listening.mp3","sections":[{"start":1,"title":"Listening"},{"start":11,"title":"Reading"},{"start":21,"title":"Grammar"},{"start":31,"title":"Word endings"},{"start":41,"title":"Buildings and activities"},{"start":51,"title":"Verb forms"}],"titleLanguage":"en","reviewedKey":true}, [{"title":"Barbara’s Call","question":"Why did Barbara call Carol?","context":"Listen to the message and answer the questions","choices":["She got the latter’s message","Just for fun","To tell her a joke","She was free"],"answer":0,"steps":["В начале голосового сообщения Барбара говорит Карол, почему пыталась до неё дозвониться.","«I got your message» означает «Я получила твоё сообщение». The latter в первом варианте — Карол."],"audio":true},{"title":"An Unanswered Call","question":"Why did Carol NOT answer? Because her mobile phone was … .","context":"Listen to the message and answer the questions","choices":["broken","stolen","on","off"],"answer":3,"steps":["После слов о предыдущем сообщении Барбара объясняет, почему не дозвонилась на мобильный Карол.","Она говорит «your mobile phone is off». Телефон был выключен — off."],"audio":true},{"title":"Carol’s Condition","question":"What was the matter with Carol? She was … .","context":"Listen to the message and answer the questions","choices":["stressed","in despair","ill","in a bad mood"],"answer":2,"steps":["Барбара рада, что Карол стало лучше, и говорит, что ей предстоит ещё неделю побыть на карантине.","Из этих реплик следует, что Карол болела — was ill."],"audio":true},{"title":"A Visit to Carol","question":"Why COULDN’T Barbara visit Carol? Because Carol was … .","context":"Listen to the message and answer the questions","choices":["against","in quarantine","in hospital","abroad"],"answer":1,"steps":["Барбара пересказывает мамину новость о том, что Карол ещё неделю должна оставаться дома. Затем говорит «so I can’t come to visit».","В записи названа причина in quarantine — на карантине."],"audio":true},{"title":"Away from School","question":"How did Carol feel without studies in Barbara’s opinion?","context":"Listen to the message and answer the questions","choices":["Happy","Scared","Bored","Disappointed"],"answer":2,"steps":["Слушай оценку Барбары перед перечислением домашней работы. Она удивляется желанию Карол узнать, что учить.","«You must be really bored» значит «Тебе, должно быть, очень скучно». Ответ Bored."],"audio":true},{"title":"What Carol Wanted to Know","question":"What did Carol want Barbara to tell her about?","context":"Listen to the message and answer the questions","choices":["Gossip","Homework","A piece of advice","The latest news"],"answer":1,"steps":["Барбара говорит «what to study», а затем перечисляет, какие темы учить и какие упражнения делать.","Карол хотела узнать домашнее задание — Homework."],"audio":true},{"title":"A Language Lesson","question":"What language does Carol study?","context":"Listen to the message and answer the questions","choices":["Japanese","Russian","French","German"],"answer":2,"steps":["Первое задание в списке — повторить неправильные глаголы и сделать упражнения 1–5. Перед перечислением назван язык.","Барбара начинает эту часть словами «For French». Ответ French."],"audio":true},{"title":"Miss Willis’s Subject","question":"Which subject does Miss Willis teach?","context":"Listen to the message and answer the questions","choices":["French","Maths","History","Geography"],"answer":1,"steps":["Имя мисс Уиллис появляется сразу после задания по математике. Барбара уточняет, что ей можно позвонить, если возникнут трудности по этому предмету.","Подразумевается, что мисс Уиллис преподаёт математику — Maths."],"audio":true},{"title":"An Exception in the Week","question":"What day was Miss Willis busy on? On … .","context":"Listen to the message and answer the questions","choices":["Thursday","Friday","Saturday","Monday"],"answer":0,"steps":["В записи названы будние вечера для звонка. Слово except вводит день, когда звонить нельзя.","Барбара говорит «except Thursday». Исключение — четверг, Thursday."],"audio":true},{"title":"Time to Call","question":"When could Carol call Miss Willis?","context":"Listen to the message and answer the questions","choices":["In the morning","In the afternoon","In the evening","At any time"],"answer":2,"steps":["В записи указан промежуток с пяти до половины седьмого. Слушай, каким словом Барбара называет это время дня.","Она говорит «any weekday evening except Thursday». Правильный ответ In the evening."],"audio":true},{"title":"The Lion at the Start","question":"What was the lion doing when the mouse was on him?","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["Sleeping","Eating","Hunting","Walking"],"answer":0,"steps":["Ответ в первом предложении. Там сказано, чем лев был занят, когда мышонок забегал по нему.","«A Lion was asleep» означает, что лев спал. Выбираем Sleeping."]},{"title":"The Lion Wakes Up","question":"What woke the lion up? The … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["Sun","hunters","King","mouse"],"answer":3,"steps":["Сначала мышонок бегал по спящему льву. Следующее предложение начинается словами «This soon woke the Lion».","This указывает на бег мышонка. Ответ mouse."]},{"title":"The Lion’s Intention","question":"What was the lion going to do? To … the mouse.","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["play with","eat","look at","kiss"],"answer":1,"steps":["Лев прижал мышонка лапой и раскрыл пасть. Фраза «ready to swallow him» уточняет намерение.","Swallow означает «проглотить». Из вариантов подходит eat."]},{"title":"The Mouse Is Caught","question":"What did the mouse do when the lion caught him?","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["He fainted","He begged for his life","He ran away","He said nothing"],"answer":1,"steps":["Мышонок обращается к льву со словами «Pardon, King» и просит простить его. Затем обещает помнить об этом.","Мышонок просил сохранить ему жизнь — He begged for his life."]},{"title":"The Lion Lets Him Go","question":"Why did the lion let the mouse go? Because he was … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["irritated","amused","angry","lazy"],"answer":1,"steps":["Мышонок предположил, что когда-нибудь поможет льву. Рассказчик говорит, что лев был «so tickled at the idea».","Tickled здесь значит «развеселился». Подходит amused."]},{"title":"When the Lion Needed Help","question":"Why did the lion need help? Because he was … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["in a hole","in a snake pit","in the zoo","caught by the people"],"answer":3,"steps":["Позже лев попал в ловушку. Охотники привязали его к дереву верёвками.","Льва поймали люди — caught by the people."]},{"title":"The Hunters’ Destination","question":"Where did the hunters decide to carry the lion to? To … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["the Zoo","the King","the circus","their children"],"answer":1,"steps":["В предложении об охотниках найди фразу «desired to carry him alive». После неё указано, к кому хотели отвезти льва.","Там стоит «to the King». Ответ the King."]},{"title":"What the Hunters Needed","question":"Why did the hunters tie the lion to a tree? Because they needed … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["a train","help","a cart","instructions"],"answer":2,"steps":["Охотники ушли «in search of a wagon to carry him on». Им было нужно средство, на котором можно везти льва.","Wagon в данном контексте — повозка, a cart."]},{"title":"A Moral for the Story","question":"Which proverb best describes the moral of this story?","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["A friend’s eye is a good mirror","An apple a day keeps the doctor away","Little friends may prove great friends","Better late than never"],"answer":2,"steps":["Маленький мышонок оказался способен выручить большого льва. Подбирай пословицу по этой связи двух эпизодов.","«Little friends may prove great friends» передаёт мысль, что маленький друг может оказать большую помощь."]},{"title":"The King of the Beasts","question":"Who is the “King of the Beasts”? The … .","context":"Read the text and answer the questions\n\nOnce a Lion was asleep and a little Mouse began running up and down him. This soon woke the Lion, who placed his huge paw on the Mouse and opened his big jaws ready to swallow him.\n\n“Pardon, King”, cried the little Mouse, “forgive me this time and I’ll never forget it. Who knows what I may be able to do for you one of these days?”\n\nThe Lion was so tickled at the idea of the Mouse being able to help him that he lifted his paw and let him go. Some time later the Lion was caught in a trap. The hunters, who desired to carry him alive to the King, tied him to a tree while they went in search of a wagon to carry him on. Just then the little Mouse happened to pass by. Seeing the unpleasant condition the Lion was in, he went up to him and gnawed away the ropes that bound the King of the Beasts.\n\n“Was I not right?” said the little Mouse. “Didn’t I help you?”","choices":["mouse","hunter","author","lion"],"answer":3,"steps":["В финале мышонок перегрызает верёвки, которыми был связан герой, попавший к охотникам.","Рассказчик называет связанного льва King of the Beasts. Ответ lion."]},{"title":"A Childhood Habit","question":"When she was a child she … .","context":"Find the correct variant","choices":["used like sweets","use to like sweets","used to like sweets","used to likes sweets"],"answer":2,"steps":["Прошлую привычку или состояние описывают конструкцией used to. После to ставь глагол в начальной форме.","Получается «she used to like sweets» — в детстве она любила сладкое."]},{"title":"An Explanation Later","question":"I will explain … .","context":"Find the correct variant","choices":["to you when I will see you","when I’ll see you","to you when I see you","you when I see you"],"answer":2,"steps":["Человек, которому что-то объясняют, ставится после explain to. В придаточном времени после when о будущем употребляется Present Simple.","Подходит «to you when I see you». Вместе «I will explain to you when I see you»."]},{"title":"How Long We’ve Known Her","question":"How long … ?","context":"Find the correct variant","choices":["do you know her for","did you knew her for","have you known her for","were you known her for"],"answer":2,"steps":["Вопрос о знакомстве, которое началось в прошлом и длится сейчас. Для такой продолжительности подходит Present Perfect.","Форма «have you known» образует «How long have you known her for?»."]},{"title":"Jim’s Party","question":"Have you … to Jim’s party?","context":"Find the correct variant","choices":["be invited too","was invited too","also invited","also been invited"],"answer":3,"steps":["Вопрос о том, пригласили ли собеседника. Для объекта действия в Present Perfect нужна пассивная конструкция have been invited.","Наречие also ставится между have и been. Получается «Have you also been invited to Jim’s party?»."]},{"title":"Identifying a Woman","question":"She’s the woman … .","context":"Find the correct variant","choices":["I spoke to her","I spoke to","what I spoke to","which I spoke to her"],"answer":1,"steps":["Определительное придаточное описывает the woman. Здесь относительное местоимение может быть опущено, потому что в придаточном оно было бы дополнением после to.","Достаточно «I spoke to». Her повторило бы уже указанное дополнение, the woman."]},{"title":"A Colleague’s Request","question":"My colleague wants … .","context":"Find the correct variant","choices":["you stay here","you to stay here","that you stay here","for you staying here"],"answer":1,"steps":["Чтобы сказать, что один человек хочет действия от другого, используй want + объект + to + начальная форма.","После wants ставим «you to stay here»."]},{"title":"A Trip to London","question":"We went to London last year, … ?","context":"Find the correct variant","choices":["are we","didn’t we","don’t we","haven’t we"],"answer":1,"steps":["Главная часть утвердительная и стоит в Past Simple. В коротком хвостике нужен отрицательный вспомогательный глагол did.","Сохраняем подлежащее we: «didn’t we?»."]},{"title":"Alan and Pizza","question":"Alan doesn’t like pizza. … .","context":"Find the correct variant","choices":["But I do","Neither do Ann","Nor Mark does","Nor we are"],"answer":0,"steps":["Во второй фразе можно выразить противоположное отношение и заменить целое «like pizza» на вспомогательный глагол do.","«But I do» означает «А я люблю». В варианте с Ann было бы «Neither does Ann»."]},{"title":"A Broken Car","question":"His car broke down. The mechanics are still working on it, so now it … .","context":"Find the correct variant","choices":["was repaired","has been repaired","has being repaired","is being repaired"],"answer":3,"steps":["Работа механиков продолжается. Машина сама подвергается ремонту, поэтому нужен пассивный залог.","Настоящий процесс выражает «is being repaired». «Has been repaired» означало бы, что ремонт уже закончен."],"reviewedEdition":true},{"title":"A Lion on the Loose","question":"The lion escaped yesterday but they still … .","context":"Find the correct variant","choices":["didn’t catched it","didn’t caught him","wasn’t caught it","haven’t caught it"],"answer":3,"steps":["Лев сбежал вчера, а говорящий сообщает о результате к настоящему моменту. После still подходит Present Perfect в отрицательной форме.","У catch третья форма — caught. Выбираем «haven’t caught it»."]},{"title":"An Ending for Wind-","question":"Wind-","context":"Add the correct ending to get a new word","choices":["y","ful","ous","or"],"answer":0,"steps":["Собери четыре варианта со словом wind и найди привычное английское слово о погоде.","Wind + y образует windy, «ветреный»."]},{"title":"An Ending for Architect-","question":"Architect-","context":"Add the correct ending to get a new word","choices":["or","ure","ous","al"],"answer":1,"steps":["Из architect нужно образовать обычное слово, называющее проектирование и внешний облик зданий.","Architect + ure даёт architecture — «архитектура»."]},{"title":"An Ending for Employ-","question":"Employ-","context":"Add the correct ending to get a new word","choices":["ous","ic","ee","ness"],"answer":2,"steps":["Employ означает «нанимать на работу». Ищи суффикс, которым можно обозначить человека, на которого направлено действие.","Employ + ee образует employee, «наёмный работник»."]},{"title":"An Ending for Awkward-","question":"Awkward-","context":"Add the correct ending to get a new word","choices":["ance","ence","full","ness"],"answer":3,"steps":["Awkward — «неловкий». Чтобы назвать качество или состояние, к прилагательному можно добавить суффикс -ness.","Получается awkwardness — «неловкость»."]},{"title":"An Ending for Sense-","question":"Sense-","context":"Add the correct ending to get a new word","choices":["dom","hood","full","less"],"answer":3,"steps":["От sense, «смысл», можно образовать прилагательное с суффиксом отсутствия признака.","Sense + less даёт senseless, «бессмысленный»."]},{"title":"An Ending for Expect-","question":"Expect-","context":"Add the correct ending to get a new word","choices":["ic","ous","ure","ing"],"answer":3,"steps":["Expect — глагол «ожидать». По предложенным окончаниям можно построить его форму на -ing.","Expect + ing даёт expecting — «ожидающий» или «ожидая»."]},{"title":"An Ending for Real-","question":"Real-","context":"Add the correct ending to get a new word","choices":["ic","ise","y","ancy"],"answer":1,"steps":["Слово real связано с реальностью. Среди предложенных частей есть британский глагольный суффикс -ise.","Real + ise образует realise — «осознавать» или «осуществлять»."]},{"title":"An Ending for Govern-","question":"Govern-","context":"Add the correct ending to get a new word","choices":["ment","dom","hood","er"],"answer":0,"steps":["Govern означает «управлять». Суффикс -ment здесь образует существительное.","Govern + ment даёт government — «правительство» или «управление»."]},{"title":"An Ending for Invent-","question":"Invent-","context":"Add the correct ending to get a new word","choices":["al","ish","ed","y"],"answer":2,"steps":["Invent — правильный глагол «изобретать». Для формы прошедшего времени к нему прибавляют -ed.","Invent + ed образует invented, «изобрёл» или «изобретённый»."]},{"title":"An Ending for Origin-","question":"Origin-","context":"Add the correct ending to get a new word","choices":["ism","ate","ous","ed"],"answer":1,"steps":["Origin — «происхождение». Среди частей есть суффикс -ate, который может образовать глагол.","Origin + ate даёт originate — «брать начало» или «возникать»."]},{"title":"Sports and Concerts","question":"It is a place for mostly sports, but sometimes for concerts or other events.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":3,"steps":["Сначала выдели главную функцию места: primarily sports. Концерты и другие события дополняют её.","Этому описанию соответствует Stadium, показанный под буквой D."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"During a Match","question":"You can see cheerleaders dancing during the match to support their favourite team.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":3,"steps":["Слова match и team указывают на спортивное состязание. Cheerleaders выступают в поддержку команды во время игры.","Из четырёх мест подходит Stadium, D."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"A Dramatic Performance","question":"It is a building in which plays and other dramatic performances are given.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":0,"steps":["Plays — пьесы. В задании их исполняют перед зрителями в здании для сценических представлений.","Это Theatre, буква A."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"Borrowing Books","question":"People can borrow books there but they should return them in time.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":2,"steps":["Borrow books означает «взять книги на время», return them — «вернуть их».","Книги выдают с условием возврата в Library, буква C."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"Where the Audience Sits","question":"People buy tickets and can sit in the boxes, dress circle, stalls or balcony there.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":0,"steps":["Boxes — ложи, stalls — партер, dress circle и balcony — ярусы зрительного зала. Такой набор характерен для здания со сценой.","Описание указывает на Theatre, вариант A."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"Genres on Screen","question":"If you buy a ticket you can watch sitcoms, fantasy, westerns, thrillers, action, Sci-Fi or animation there.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":1,"steps":["В списке названы жанры экранных произведений, в том числе анимация и вестерн. Вопрос о месте, куда за просмотр покупают билет.","Фильмы показывают в Cinema, буква B."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"A Film with 3D Glasses","question":"Sometimes, to enjoy the experience of the film you must wear 3D glasses there.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":1,"steps":["Найди два ключа: film и 3D glasses. Очки нужны для просмотра стереоскопического фильма на экране.","Это Cinema, вариант B."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"Working with Documents","question":"If you are going to write a scientific report you should go there to work with the documents.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":2,"steps":["Для научного доклада нужны источники, которые можно найти и изучить в читальном зале.","Из показанных зданий подходит Library, буква C."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"World Sporting Events","question":"These huge, modern, well-equipped constructions are usually built to hold world championships and Olympic Games.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":3,"steps":["Hold a championship значит «провести чемпионат». В вопросе речь о сооружениях для крупных спортивных соревнований.","Подходит Stadium, буква D."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"Meeting Film Stars","question":"After the first performance of a blockbuster there you can see the actors who star in this film.","context":"Read the sentences, look at the pictures and choose the correct variant","choices":["Theatre","Cinema","Library","Stadium"],"answer":1,"steps":["Blockbuster здесь означает популярный фильм, а first performance — его премьерный показ.","Премьера фильма проходит в Cinema, вариант B."],"figure":{"src":"assets/british-bulldog/2018/7-8/buildings.webp","alt":"Four buildings with labels. A is Theatre, B is Cinema, C is Library and D is Stadium.","width":1303,"height":1308}},{"title":"A Purse at Home","question":"She has … her purse at home.","context":"Fill in the blanks","choices":["leave","left","forgot","forgottened"],"answer":1,"steps":["После has в Present Perfect нужна третья форма глагола. У leave формы leave, left, left.","Получается «She has left her purse at home» — она оставила сумочку дома."]},{"title":"After the Accident","question":"He … calm after the accident.","context":"Fill in the blanks","choices":["left","stay","had","remained"],"answer":3,"steps":["В выражении нужно передать, что человек продолжал сохранять спокойствие после события. Требуется прошедшая форма.","«He remained calm» — «Он остался спокоен». Для stay потребовалось бы stayed."]},{"title":"Breaking an Arm","question":"He … down and broke his arm.","context":"Fill in the blanks","choices":["fallen","fell","fall","filled"],"answer":1,"steps":["Союз and связывает два прошедших действия. Для падения выбери прошедшую форму от fall.","Форма Past Simple — fell. Получается «He fell down and broke his arm»."]},{"title":"Mr Brown in Bed","question":"Mr Brown … in bed because he was ill.","context":"Fill in the blanks","choices":["lie","lied","lain","lay"],"answer":3,"steps":["«Лежать» — lie. У этого глагола формы lie, lay, lain. Lied относится к другому lie, «лгать».","В Past Simple подходит lay in bed — «лежал в постели»."]},{"title":"Getting Up from the Sofa","question":"The doctor asked me not to … from the sofa.","context":"Fill in the blanks","choices":["rise","raise","rose","risen"],"answer":0,"steps":["После not to нужна начальная форма. Подъём совершается самим человеком и не имеет прямого дополнения.","Это rise. Raise обычно означает «поднимать что-то» и требует дополнения."]},{"title":"Birds in Autumn","question":"In autumn the birds … away to warm countries.","context":"Fill in the blanks","choices":["flown","flowed","fly","flow"],"answer":2,"steps":["Об осеннем перелёте говорится как о повторяющемся явлении. Нужен Present Simple с подлежащим the birds.","Выбираем fly away — «улетают». Flown — форма причастия от fly."]},{"title":"A Greeting by Hand","question":"She couldn’t even … her hand to greet her friend.","context":"Fill in the blanks","choices":["rise","raise","rose","raised"],"answer":1,"steps":["После couldn’t ставится начальная форма. Прямое дополнение her hand требует глагола «поднимать что-то».","Подходит «raise her hand». Rise описывает подъём самого подлежащего."]},{"title":"An Unexpected Result","question":"He didn’t … his friend to fail the exam.","context":"Fill in the blanks","choices":["wait","expect","expecting","expected"],"answer":1,"steps":["После didn’t употребляется начальная форма. Смысл фразы — он не ожидал, что друг провалит экзамен.","Сочетание «expect his friend to fail» строится по модели expect somebody to do something. Ответ expect."]},{"title":"An Apology and Departure","question":"He apologised and … the room.","context":"Fill in the blanks","choices":["lived","leave","left","live"],"answer":2,"steps":["Ищи форму «покинул комнату». Вторая часть соединена с прошедшим apologised, поэтому нужен Past Simple.","Прошедшая форма leave — left. «Left the room» значит «вышел из комнаты»."]},{"title":"Trust in a Conversation","question":"We understood that he was … to us.","context":"Fill in the blanks","choices":["laying","lying","lieing","laining"],"answer":1,"steps":["Для действия в процессе используем was + форму на -ing. Здесь lie означает «лгать».","У lie в этой форме ie заменяется на y: lying. Получается «he was lying to us»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
